            errors = errors + 1;
        end
        if (ena !== 4'b0001) begin
            $display("ERROR: Reset state ena is %b, expected 0001", ena);
            errors = errors + 1;
        end

        // Release reset
        reset = 0;
        #2;

        // Verify through a series of counts, checking boundary overflows and enables
        // Test normal counting up to 10 (ones rollover)
        for (i = 0; i <= 10; i = i + 1) begin
            // Check expected values before clock edge or right after
            #10;
        end

        // Let's do a targeted directed test for rollover sequences
        // Reset and test full cascade up to 9999 and roll over to 0000
        reset = 1;
        #10;
        reset = 0;
        #2;

        // Fast forward / cycle through specific important milestones
