        // Force or step to 8 then pulse
        // Instead of 10000 cycles, let's test specific transitions by resetting 
        // and using specific checks or checking small ranges.
        // Let's run a bounded check of the first 100 cycles to ensure correct incrementing.

        for (i = 0; i < 105; i = i + 1) begin
            // Calculate expected BCD value mathematically for verification
            // (Just checking that it doesn't contain invalid BCD values like A-F)
            reg [3:0] exp_ones;
            reg [3:0] exp_tens;
            reg [3:0] exp_hundreds;
            reg [3:0] exp_thousands;

            exp_ones      = (i     ) % 10;
            exp_tens      = (i / 10) % 10;
            exp_hundreds  = (i / 100) % 10;
            exp_thousands = (i / 1000) % 10;

            if (q[3:0] !== exp_ones) begin
                $display("ERROR at cycle %0d: ones = %h, expected %h", i, q[3:0], exp_ones);
                errors = errors + 1;
            end
            if (q[7:4] !== exp_tens) begin
                $display("ERROR at cycle %0d: tens = %h, expected %h", i, q[7:4], exp_tens);
                errors = errors + 1;
            end
            if (q[11:8] !== exp_hundreds) begin
                $display("ERROR at cycle %0d: hundreds = %h, expected %h", i, q[11:8], exp_hundreds);
                errors = errors + 1;
            end
            if (q[15:12] !== exp_thousands) begin
                $display("ERROR at cycle %0d: thousands = %h, expected %h", i, q[15:12], exp_thousands);
                errors = errors + 1;
            end

            // Check enable signals
            if (ena[0] !== 1'b1) begin
                errors = errors + 1;
            end
            if (ena[1] !== (exp_ones == 4'd9)) begin
                $display("ERROR at cycle %0d: ena[1] = %b, expected %b", i, ena[1], (exp_ones == 4'd9));
                errors = errors + 1;
            end
            if (ena[2] !== ((exp_ones == 4'd9) && (exp_tens == 4'd9))) begin
                errors = errors + 1;
            end
            if (ena[3] !== ((exp_ones == 4'd9) && (exp_tens == 4'd9) && (exp_hundreds == 4'd9))) begin
                errors = errors + 1;
            end

            #10;
        end

        // Final result evaluation
        if (errors == 0) begin
            $display("*** TEST RESULT: PASS ***");
        end else begin
            $display("*** TEST RESULT: FAIL ***");
        end
        $finish;
    end

endmodule
